import numpy as np
lines=open("complex_init.xyz").read().split("\n")[2:]
atoms=[]
for l in lines:
    if l.strip():
        p=l.split(); atoms.append((p[0], np.array(list(map(float,p[1:4])))))
lig=[(s,p) for s,p in atoms[:55]]; cym=[(s,p) for s,p in atoms[55:]]
pairs=[]
for i,(s,p) in enumerate(lig):
    for j,(t,q) in enumerate(cym):
        pairs.append((np.linalg.norm(p-q), i, s, j+55, t))
pairs.sort()
for d,i,s,j,t in pairs[:8]:
    print(round(d,2), i, s, j, t)
